/**
 * Turning a material document into the Markdown file in docs/materials.
 *
 * Nothing clever: one block becomes one Markdown construct. A pipe inside a
 * table cell is escaped, because that is the one character that would break a
 * row, and the generated files are checked byte for byte by `npm run verify`.
 */

import type { MaterialBlock, MaterialDoc } from './types.js';

export const MATERIALS_NOTE =
  '<!-- Generated by `npm run benchmarks` from src/shared/materials. Do not edit by hand. -->';

function cell(text: string): string {
  return text.replace(/\|/g, '\\|');
}

function blockLines(block: MaterialBlock): string[] {
  switch (block.kind) {
    case 'heading':
      return [`## ${block.text}`];
    case 'subheading':
      return [`### ${block.text}`];
    case 'paragraph':
      return [block.text];
    case 'bullets':
      return block.items.map((item) => `- ${item}`);
    case 'steps':
      return block.items.map((item, index) => `${String(index + 1)}. ${item}`);
    case 'note':
      return [`> ${block.text}`];
    case 'formula':
      // An indented line is a code block in every Markdown reader.
      return [`    ${block.text}`];
    case 'table':
      return [
        `**${block.caption}**`,
        '',
        `| ${block.columns.map(cell).join(' | ')} |`,
        `| ${block.columns.map(() => '---').join(' | ')} |`,
        ...block.rows.map((row) => `| ${row.map(cell).join(' | ')} |`),
      ];
    default: {
      const never: never = block;
      return [String(never)];
    }
  }
}

export function markdownFor(doc: MaterialDoc): string {
  const lines: string[] = [`# ${doc.title}`, '', MATERIALS_NOTE, '', doc.intro];
  for (const block of doc.blocks) {
    lines.push('', ...blockLines(block));
  }
  return `${lines.join('\n')}\n`;
}
